package main
import("encoding/json";"fmt";"math")
type history_reference struct{Version string `json:"version"`;Method string `json:"method_sha256"`;Profile string `json:"profile"`;Source string `json:"source_id"`;State string `json:"state"`;Low *history_fit `json:"initial_low_fit"`;Middle *history_fit `json:"middle_diagnostic_fit"`;Hold map[string]interface{} `json:"initial_low_holdout"`;Return map[string]interface{} `json:"return_against_initial_prediction"`}
func(job *history_job)read_reference(path string)(history_reference,string,error){r:=history_reference{};data,err:=history_read(path);if err!=nil{return r,"",err};if err=history_unique_json(data);err!=nil{return r,"",err};if err=json.Unmarshal(data,&r);err!=nil{return r,"",err};if r.Version!=history_version||r.Method!=history_method_sha||r.Source!=job.timing.Source||r.State!="geometry_observed_analysis_descriptive"||r.Low==nil||r.Middle==nil{return r,"",fmt.Errorf("reference version/method/source/geometry/fits mismatch")};if _,ok:=history_profiles[r.Profile];!ok{return r,"",fmt.Errorf("unknown reference profile")};for _,fit:=range []*history_fit{r.Low,r.Middle}{for _,v:=range fit.Beta{if math.IsNaN(v)||math.IsInf(v,0){return r,"",fmt.Errorf("nonfinite reference")}};if fit.Amplitude<0||math.Abs(fit.Amplitude-math.Hypot(fit.Beta[0],fit.Beta[1]))>1e-9{return r,"",fmt.Errorf("inconsistent reference amplitude")}};return r,history_hash(data),nil}
func(job *history_job)add_references(result map[string]interface{})error{refs:=map[string]interface{}{};p:=history_profiles[job.profile];low,_:=result["initial_low_fit"].(*history_fit);if job.noop!=""{r,hash,err:=job.read_reference(job.noop);if err!=nil{return err};rp:=history_profiles[r.Profile];if rp[0]!=p[0]||rp[1]!=32{return fmt.Errorf("no-op reference must match contributor count")};observation:=map[string]interface{}{"path":job.noop,"sha256":hash,"profile":r.Profile,"initial_low_fit":r.Low,"initial_low_holdout":r.Hold,"return_against_initial_prediction":r.Return,"middle_transfer_from_initial":history_transfer(*r.Low,*r.Middle),"interpretation":"actual no-op baseline retained; no subtraction or tolerance inferred"};if low!=nil{observation["initial_transfer_to_current"]=history_transfer(*r.Low,*low)};refs["noop"]=observation};if job.calibration!=""{r,hash,err:=job.read_reference(job.calibration);if err!=nil{return err};rp:=history_profiles[r.Profile];if rp[0]!=1||rp[1]!=p[1]{return fmt.Errorf("N1 calibration must match middle TL")};cal:=history_transfer(*r.Low,*r.Middle);cal["path"],cal["sha256"],cal["profile"]=job.calibration,hash,r.Profile;cal["interpretation"]="matched N1 transfer is descriptive; not proof all32 voices share it or high TL0 extrapolation is valid";if gain,ok:=cal["amplitude_gain"].(*float64);ok&&gain!=nil&&low!=nil{if mid,ok:=result["middle_diagnostic_fit"].(*history_fit);ok{expected:=[2]float64{*gain*low.Beta[0],*gain*low.Beta[1]};cal["unfitted_common_scalar_ac_coefficients"]=expected;cal["middle_ac_coefficient_distance_pcm"]=math.Hypot(mid.Beta[0]-expected[0],mid.Beta[1]-expected[1]);if own:=history_transfer(*low,*mid)["phase_delta_cos_sin_radians"];own!=nil{a,aok:=own.(*float64);b,bok:=cal["phase_delta_cos_sin_radians"].(*float64);if aok&&bok&&a!=nil&&b!=nil{cal["phase_transfer_difference_radians"]=history_wrap(*a-*b)}}}};refs["n1_calibration"]=cal};if len(refs)>0{result["references"]=refs};return nil}
